function event_loot(e)
    if (e.item:GetID() == 56014 and e.corpse:GetNPCTypeID() == 96368) then
        local qglobals = eq.get_qglobals(e.self);
        if (qglobals["cleric20"] ~= nil and qglobals["cleric20"] >= "3") then
